const { Rest } = require('mediawiki-rest-api');
const mw = require('mediawiki');

class CodeMirrorLint {
    constructor(restClient) {
        this.restClient = restClient;
        this.currentRequest = null;
    }

    async execute(doc) {
        if (this.currentRequest) {
            this.currentRequest.abort();
        }

        try {
            const response = await this.makeRequest(doc);
            return response.data;
        } catch (error) {
            mw.log.warn('[CodeMirror] Error during linting:', error);
            throw error;
        }
    }

    async makeRequest(doc) {
        return new Promise((resolve, reject) => {
            const controller = new AbortController();
            this.currentRequest = controller;

            setTimeout(() => {
                controller.abort();
                reject(new Error('Request timed out'));
            }, 3000); // 3 seconds timeout

            this.restClient.post('/v1/transform/wikitext/to/lint', {
                wikitext: doc.toString()
            }, { signal: controller.signal })
            .then(response => resolve(response))
            .catch(error => reject(error));
        });
    }
}

module.exports = CodeMirrorLint;
